PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS artists(id TEXT PRIMARY KEY,name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,description TEXT NOT NULL DEFAULT '',cover TEXT NOT NULL DEFAULT '',accent TEXT NOT NULL DEFAULT '#9168eb',published INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS albums(id TEXT PRIMARY KEY,title TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,artist_id TEXT NOT NULL REFERENCES artists(id),year INTEGER NOT NULL,cover TEXT NOT NULL DEFAULT '',genre TEXT NOT NULL DEFAULT '',release_type TEXT NOT NULL DEFAULT '',published INTEGER NOT NULL DEFAULT 1);
CREATE INDEX IF NOT EXISTS idx_albums_artist ON albums(artist_id);
CREATE TABLE IF NOT EXISTS tracks(id TEXT PRIMARY KEY,title TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,artist_id TEXT NOT NULL REFERENCES artists(id),album_id TEXT NOT NULL REFERENCES albums(id),duration INTEGER NOT NULL DEFAULT 0,audio_url TEXT NOT NULL DEFAULT '',cover TEXT NOT NULL DEFAULT '',plays INTEGER NOT NULL DEFAULT 0,track_number INTEGER NOT NULL DEFAULT 0,source_status TEXT NOT NULL DEFAULT 'unverified',source_page TEXT NOT NULL DEFAULT '',published INTEGER NOT NULL DEFAULT 1);
CREATE INDEX IF NOT EXISTS idx_tracks_artist ON tracks(artist_id);
CREATE INDEX IF NOT EXISTS idx_tracks_album_number ON tracks(album_id,track_number);
CREATE INDEX IF NOT EXISTS idx_tracks_plays ON tracks(published,plays DESC);
CREATE TABLE IF NOT EXISTS genres(id TEXT PRIMARY KEY,name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,display_name TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS playlists(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id),title TEXT NOT NULL,is_public INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS playlist_tracks(playlist_id TEXT NOT NULL REFERENCES playlists(id) ON DELETE CASCADE,track_id TEXT NOT NULL REFERENCES tracks(id),position INTEGER NOT NULL,PRIMARY KEY(playlist_id,position));
CREATE TABLE IF NOT EXISTS favorites(user_id TEXT NOT NULL REFERENCES users(id),track_id TEXT NOT NULL REFERENCES tracks(id),PRIMARY KEY(user_id,track_id));
